+
+    main {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 2rem 1rem;
+    }
+
+    .card {
+      width: min(100%, 28rem);
+      padding: 2rem;
+      border: 1px solid var(--border);
+      border-radius: 1.25rem;
+      background: linear-gradient(180deg, var(--panel), var(--panel-2));
+      box-shadow: 0 24px 60px var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 0.5rem;
+      font-size: clamp(1.5rem, 3vw, 2rem);
+      line-height: 1.15;
+    }
+
+    p {
+      margin: 0;
+      color: var(--muted);
+    }
+
+    form {
+      margin-top: 1.5rem;
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid var(--border);
+      border-radius: 1rem;
+      background: rgba(255, 255, 255, 0.02);
+    }
+
+    .consent-row {
+      display: flex;
+      gap: 0.85rem;
+      align-items: flex-start;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0.18rem 0 0;
+      accent-color: var(--accent);
+      flex: none;
+    }
+
+    label {
+      display: block;
+      cursor: pointer;
+      color: var(--text);
+      font-weight: 600;
+    }
+
+    .required-mark {
+      color: var(--accent-strong);
+    }
+
+    .helper-text {
+      margin-top: 0.35rem;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .actions {
+      margin-top: 1.25rem;
+      display: flex;
+      justify-content: flex-end;
+    }
+
+    button {
+      border: 1px solid transparent;
+      border-radius: 0.9rem;
+      padding: 0.85rem 1.1rem;
+      font: inherit;
+      font-weight: 700;
+      color: #0b1020;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      cursor: pointer;
+      transition: transform 0.15s ease, filter 0.15s ease;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    button:active {
+      transform: translateY(1px);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible,
+    .skip-link:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      margin-top: 1rem;
+      min-height: 1.5rem;
+      color: var(--success);
+      font-weight: 600;
+    }
+
+    @media (max-width: 420px) {
+      .card {
+        padding: 1.25rem;
+      }
+
+      .actions {
+        justify-content: stretch;
+      }
+
+      button {
+        width: 100%;
+      }
+    }
+
+    @media (forced-colors: active) {
+      :root {
+        --bg: Canvas;
+        --panel: Canvas;
+        --panel-2: Canvas;
+        --text: CanvasText;
+        --muted: CanvasText;
+        --border: ButtonBorder;
+        --accent: ButtonText;
+        --accent-strong: ButtonText;
+        --focus: Highlight;
+        --success: CanvasText;
+      }
+
+      .card,
+      .form-field,
+      button {
+        border-color: ButtonBorder;
+      }
+
+      button {
+        forced-color-adjust: auto;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main">Skip to main content</a>
+
+  <main id="main">
+    <section class="card" aria-labelledby="consent-title">
+      <h1 id="consent-title">Consent to the Terms of Use</h1>
+      <p>Review and confirm before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="consent-row">
+            <input
+              id="terms"
+              name="terms"
+              type="checkbox"
+              required
+              aria-describedby="terms-help"
+            >
+            <div>
+              <label for="terms">
+                I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
+              </label>
+              <div class="helper-text" id="terms-help">Required to submit the form.</div>
+            </div>
+          </div>
+        </div>
+
+        <div class="actions">
+          <button type="submit">Submit</button>
+        </div>
+
+        <div class="status" id="status" aria-live="polite"></div>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms');
+    const status = document.getElementById('status');
+
+    form.addEventListener('submit', (event) => {
+      if (!form.checkValidity()) {
+        status.textContent = '';
+        return;
+      }
+
+      event.preventDefault();
+      status.textContent = 'Consent saved.';
+      checkbox.setAttribute('aria-invalid', 'false');
+    });
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        checkbox.removeAttribute('aria-invalid');
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
